/**  Maps monotonic time to call-relative offsets and wall time. */
export type SessionClock = {
	t0_mono: number,
	/**  Unix milliseconds at `t0_mono`. */
	t0_wall_ms: number,
};

export type SessionPhase = "idle" | "starting" | "recording" | "paused" | "stopping";

/**  Full resync payload (`session_snapshot`): lagging subscribers rebuild from it. */
export type SessionSnapshot = {
	state: SessionState,
	clock: SessionClock | null,
	transcript: TranscriptLine[],
	queue: QueueState,
};

export type SessionState = {
	phase: SessionPhase,
	call: Ulid | null,
	/**  True while the demo/replay feed drives the session. */
	demo: boolean,
};

export type Settings = {
	schema_version?: number,
	ui?: UiSettings,
	onboarding?: OnboardingSettings,
	vault?: VaultSettings,
	audio?: AudioSettings,
	stt?: SttSettings,
	llm?: LlmSettings,
	overlay?: OverlaySettings,
	capture?: CaptureSettings,
	binds?: BindSpec[],
	stealth?: StealthSettings,
	updates?: UpdateSettings,
	templates?: Template[],
};

/**  Partial settings as a JSON merge patch (objects merge, arrays replace). */
export type SettingsPatch = unknown;

export type ShotItem = {
	id: string,
	at_s: number,
	rel_path: string,
	title: string,
	caption: string,
	/**  `manual` | `auto`. */
	source: string,
};

/**
 *  One entry of the audio source picker (`source_list` / `source_list_installed`).
 *  `id` is what goes into `Target::App(id)` (bundle id on macOS, exe path on
 *  Windows) or the literal `"system"` for [`SourceKind::System`].
 */
export type SourceInfo = {
	id: string,
	name: string,
	bundle_id: string,
	/**  Main process id, 0 when the app is not running. */
	pid: number,
	/**  Small PNG (<= 64 px) as base64 without the `data:` prefix. */
	icon_png_b64: string | null,
	producing_audio: boolean,
	kind: SourceKind,
};

/**  Kind of an audio source in the picker. */
export type SourceKind = "app" | 
/**  Everything except our own process tree. */
"system";

export type StartOpts = {
	title: string | null,
	folder: FolderRef | null,
	system: Target | null,
	mic: string | null,
	demo: boolean,
};

export type StealthSettings = {
	/**  Also exclude the main window from capture (off by default). */
	hide_main?: boolean,
	verify_interval_ms?: number,
};

export type StealthStatus = { state: "verified" } | { state: "degraded"; reason: string } | { state: "unavailable"; reason: string };

/**  `store://changed` payload. */
export type StoreChange = {
	kind: StoreChangeKind,
	id: Ulid,
	is_folder: boolean,
};

export type StoreChangeKind = "created" | "updated" | "moved" | "trashed" | "restored" | "removed";

/**  Audio stream identity. UI labels: «Я» / «Система». */
export type Stream = "me" | "system";

/**  Per-stream STT health for the debug page. */
export type StreamDiag = {
	stream: Stream,
	/**
	 *  Newest audio fed -> partial/final emitted by the engine (queue + compute),
	 *  the part of word-to-screen the app controls. Algorithmic look-ahead of the
	 *  model is on top (see `lookahead_ms` of `SttDiagnostics`).
	 */
	emit_lag: Percentiles,
	/**  End of speech -> final emitted. */
	final_lag: Percentiles,
	backlog_ms: number,
	restarts: number,
};

export type StreamingMode = "native" | "pseudo";

export type SttBenchmark = {
	engine: string,
	rtf: number | null,
	p95_final_ms: number,
	app_version: string,
};

/**  `stt_diagnostics` payload. */
export type SttDiagnostics = {
	engine: string,
	lookahead_ms: number,
	streams: StreamDiag[],
	corrected: number,
	correction_skipped: number,
	correction_lag: Percentiles,
};

/**  Engine failure surfaced through the sink (isolated per stream). */
export type SttError = {
	stream: Stream,
	message: string,
	/**  True when the engine host will restart the worker by itself. */
	recoverable: boolean,
};

/**  One revision of one utterance. `stt://segment` payload. */
export type SttEvent = {
	stream: Stream,
	utt: number,
	/**  Revision of the same utterance (monotonic). */
	rev: number,
	kind: SttKind,
	text: string,
	lang: string | null,
	t_start_ns: number,
	t_audio_end_ns: number,
	t_emit_ns: number,
};

export type SttKind = "partial" | "final";

export type SttSettings = {
	/**  Engine id from `EngineRegistry`; empty = chosen by the hardware check. */
	engine?: string,
	languages?: string[],
	vocab_hints?: string[],
	/**  Phrases dropped by the hallucination filter (editable). */
	hallucination_phrases?: string[],
	/**  Cloud vendor when a cloud engine is selected (`soniox` | `deepgram`). */
	cloud_vendor?: string,
	/**  Re-transcribe finished utterances with Whisper in the background (local engines only). */
	background_correction?: boolean,
	/**  Cached hardware benchmark: (engine id, RTF). */
	benchmark?: SttBenchmark | null,
};

export type SttTier = 
/**  Larger local model (accurate/streaming) should run comfortably. */
"local_high" | 
/**  Only a small local model is plausible. */
"local_light" | 
/**  Recommend cloud transcription. */
"cloud";

/**  Audio source selection types shared by audio, session and UI. */
export type Target = 
/**  Bundle id (macOS) or exe path (Windows). */
{ kind: "app"; id: string } | { kind: "whole_system" };

/**  Prompt template. Lives in the *user* turn, never in the system prompt. */
export type Template = {
	id: string,
	names: LocalizedName,
	instruction: string,
	needs_my_answer?: boolean,
	vision?: boolean,
	reasoning?: boolean,
};

/**  `overlay://tone` payload: inputs of the adaptive CSS tokens. */
export type Tone = {
	tone: ToneKind,
	rgb: string,
	fg: string,
	inv: string,
	int: string,
	mv: string,
	luma: number | null,
	busy: number | null,
	/**
	 *  Minimum scrim opacity (0..1) that keeps WCAG 4.5:1 for the worst-case
	 *  backdrop pixel. The UI scrim is `max(k * .85, scrim_min)`.
	 */
	scrim_min?: number | null,
	/**
	 *  F5: per-region tones (the region under the overlay split `cols` x `rows`,
	 *  row-major, top-left first). `None` only from old senders; the UI then uses
	 *  the global fields above for every region.
	 */
	grid?: ToneGrid | null,
};

/**
 *  Per-region tones under the overlay. Each cell is a full [`Tone`] with its own
 *  palette / scrim floor (its own `grid` is always `None`).
 */
export type ToneGrid = {
	cols: number,
	rows: number,
	/**  `cols * rows` entries, row-major. */
	cells: Tone[],
};

export type ToneKind = "dark" | "light" | "color";

export type ToneMode = "auto" | "light" | "dark";

/**  A line of the live transcript as kept by `TranscriptBuf`. */
export type TranscriptLine = {
	seq: number,
	stream: Stream,
	offset_s: number,
	text: string,
	is_final: boolean,
};

export type Trigger = { kind: "combo"; mods: Mods; key: KeyCode } | { kind: "modifier_only"; mods: Mods } | { kind: "mouse"; button: MouseBtn; mods: Mods };

export type UiLanguage = "auto" | "ru" | "en";

export type UiSettings = {
	language?: UiLanguage,
	font_px?: number,
};

/**  ULID, serialized as its 26-char string. Identity of calls, folders, docs. */
export type Ulid = string;

export type UpdateSettings = {
	/**  The only automatic network call; on by default. */
	check_daily?: boolean,
	/**  RFC 3339 time of the last check. */
	last_checked?: string | null,
};

export type UpdateStatus = {
	/**  False until the release signing keys exist (docs/DECISIONS-M0.md). */
	enabled: boolean,
	current: string,
	available: string | null,
};

export type Utterance = {
	at_s: number,
	speaker: Stream,
	text: string,
};

/**  `vault_open` / `vault_info` payload. */
export type VaultInfo = {
	/**  Absolute path of the open vault. */
	path: string,
};

export type VaultSettings = {
	path?: string,
	/**  On-disk names of the reserved system folders. */
	unsorted_dir?: string,
	trash_dir?: string,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

